class RadLexService:
    @staticmethod
    def get_term(rid: str) -> Optional[RadLexTerm]:
        return RADLEX_DATABASE.get(rid.strip())

    @staticmethod
    def get_critical_findings() -> List[RadLexTerm]:
        return [t for t in RADLEX_DATABASE.values() if t.is_critical_finding]
